package ug.audiocity.studio;
import java.io.*;import java.nio.file.*;
/** Optional personal Addictive Afrobeat one-shots. Audio is imported, never bundled in the APK. */
public final class AfroDrumPack {
 private AfroDrumPack(){}
 public static final String FILE="addictive-afrobeat-drums.acpack",NAME="Addictive Afrobeat Drum One-Shots";
 public static final String[] FILES={"04_10_conga.wav.wav","Addctive Maracas  (1).wav","Addctive Stick.wav","INSTIMBAL3.WAV","INSTIMBAL4.WAV","KSHMR Orchestra Clank 03.wav","KSHMR Orchestra Hit 09.wav","KSHMR Percussion Flam 11.wav","SB - Omo Alhaji [Perc].wav","SB - Perc (9).wav","VEDH Snare 024.wav","VEH1 Tom - 05.wav","vybeBeenOnClap.wav","Wood Liebing 4.wav"};
 public static final String[] TITLES={"Conga · 04 10","Addictive Maracas","Addictive Stick","Timbal 3","Timbal 4","KSHMR Orchestra Clank 03","KSHMR Orchestra Hit 09","KSHMR Percussion Flam 11","SB Omo Alhaji Perc","SB Perc 9","VEDH Snare 024","VEH1 Tom 05","Vybe Been On Clap","Wood Liebing 4"};
 private static void validate(SampledInstruments.Pack pack)throws IOException{if(!NAME.equals(pack.name)||pack.regions.length!=FILES.length)throw new IOException("Choose AudioCity-Addictive-Afrobeat-Drums.acpack. This pack must contain all 14 drum one-shots.");for(int i=0;i<FILES.length;i++){SampledInstruments.Region r=pack.regions[i];if(r.root!=36+i||r.low!=36+i||r.high!=36+i||r.loop)throw new IOException("Unexpected Afro drum mapping");}}
 public static boolean available(File project,File app){return project!=null&&new File(project,FILE).isFile()||app!=null&&new File(app,FILE).isFile();}
 public static SampledInstruments.Pack load(File project,File app)throws IOException{File base=project!=null&&new File(project,FILE).isFile()?project:app;if(base==null||!new File(base,FILE).isFile())throw new IOException("Addictive Afrobeat drums are not imported. Use Tools → Import Afro drum pack.");SampledInstruments.Pack pack=InstrumentArchive.read(base,FILE);validate(pack);return pack;}
 public static void copyToProject(File app,File project)throws IOException{if(project==null||new File(project,FILE).isFile())return;File source=new File(app,FILE);if(!source.isFile())throw new IOException("Import the Afro drum pack first.");File temp=File.createTempFile("afro-copy-",".tmp",project);try{Files.copy(source.toPath(),temp.toPath(),StandardCopyOption.REPLACE_EXISTING);Files.move(temp.toPath(),new File(project,FILE).toPath(),StandardCopyOption.REPLACE_EXISTING);}finally{temp.delete();}}
 public static void install(InputStream input,File app)throws IOException{File temp=File.createTempFile("afro-import-",".acpack",app);try{long total=0;try(OutputStream out=new BufferedOutputStream(new FileOutputStream(temp))){byte[] buffer=new byte[32768];int n;while((n=input.read(buffer))!=-1){total+=n;if(total>160L*1024*1024)throw new IOException("Afro drum pack is too large");out.write(buffer,0,n);}}validate(InstrumentArchive.read(app,temp.getName()));Files.move(temp.toPath(),new File(app,FILE).toPath(),StandardCopyOption.REPLACE_EXISTING);}finally{temp.delete();}}
 public static boolean used(BeatPilotDrumPattern pattern){for(int lane=0;lane<8;lane++)if(!pattern.imported(lane)&&DrumSampleCatalog.isAfro(lane,pattern.sampleChoice(lane)))return true;return false;}
 public static boolean used(Core.Session session){for(PatternLibrary.Entry entry:session.patterns)if(used(BeatPilotDrumPattern.decode(entry.data)))return true;return false;}
}
